<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/employer-functions.php';
$user = require_employer();
$stmt = db()->prepare('SELECT id,title,message,is_read,created_at FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 100');
$stmt->execute([(int)$user['id']]); $notifications = $stmt->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Notifications — HireSwipe</title><link rel="stylesheet" href="<?= e(url('assets/css/employer.css')) ?>"></head><body class="hs-body"><header class="hs-header"><a class="hs-brand" href="<?= e(url('employer/home.php')) ?>"><span class="hs-mark">H</span><span>HireSwipe<small>Talent, without the noise.</small></span></a><nav class="hs-nav"><a href="<?= e(url('employer/home.php')) ?>">Discover</a><a href="<?= e(url('employer/search.php')) ?>">Search</a><a class="nav-active" href="<?= e(url('employer/notifications.php')) ?>">Notifications</a><a class="signout" href="<?= e(url('auth/logout.php')) ?>">Sign out</a></nav></header><main class="notifications-main"><a class="back-link" href="<?= e(url('employer/home.php')) ?>">← Back to discovery</a><section class="notifications-heading"><span class="eyebrow">STAY IN THE LOOP</span><h1>Your <em>updates.</em></h1><p>Important activity and updates for your HireSwipe account.</p></section><?php if ($notifications): ?><div class="notification-list"><?php foreach ($notifications as $n): ?><article class="notification-item <?= !$n['is_read'] ? 'unread' : '' ?>"><div class="notification-symbol">✦</div><div class="notification-copy"><h2><?= e($n['title']) ?><?php if (!$n['is_read']): ?><span class="unread-label">NEW</span><?php endif; ?></h2><p><?= e($n['message']) ?></p><time datetime="<?= e(date(DATE_ATOM, strtotime($n['created_at']))) ?>"><?= e(date('M j, Y · g:i a', strtotime($n['created_at']))) ?></time></div><?php if (!$n['is_read']): ?><form method="post" action="<?= e(url('actions/notification-action.php')) ?>"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="notification_id" value="<?= (int)$n['id'] ?>"><button class="mark-read" type="submit">Mark read</button></form><?php endif; ?></article><?php endforeach; ?></div><?php else: ?><section class="empty-state notification-empty"><div class="empty-orbit"><div class="empty-icon">🔔</div><span class="orbit-dot dot-one"></span><span class="orbit-dot dot-two"></span></div><span class="eyebrow">ALL QUIET FOR NOW</span><h2>No notifications yet</h2><p>When there’s an update for your account, you’ll find it here.</p><a class="primary-link" href="<?= e(url('employer/home.php')) ?>">Back to discovery <span>→</span></a></section><?php endif; ?></main></body></html>
